"""Trim and upper-case label."""

NAME = "tidy-label"
SPEC = {"op": "tidy", "field": "label"}
FIELD = SPEC["field"]

def apply(rec):
    v = rec.get(FIELD)
    if not isinstance(v, str):
        return rec
    return {**rec, FIELD: v.strip().upper()}

